// Builds the customer reply. Sits between "Execute a SQL query" and the Gmail "Send a message" node.
// It reads the interpreted requirements from the node named "Code in JavaScript2".
const req = $('Code in JavaScript2').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.product_name);

const inr = n => '₹' + Number(n).toLocaleString('en-IN');
const lines = ['Hello,', ''];

if (req.needs_clarification) {
  lines.push(
    'Thank you for your enquiry. To recommend the right laptop, could you please tell me:',
    '- your maximum budget (for example, ₹80,000)',
    '- the RAM you need (for example, 16 GB)',
    '- any storage or brand preference'
  );
} else if (rows.length === 0) {
  lines.push('Thank you for your enquiry. Here is how I understood your request:');
  req.assumptions.forEach(a => lines.push('- ' + a));
  lines.push(
    '',
    'Unfortunately, I could not find a laptop in our list that meets all of these requirements.',
    'You could try a slightly higher budget or a lower RAM requirement, and I will search again.'
  );
} else {
  lines.push('Thank you for your enquiry. Here is how I understood your request:');
  req.assumptions.forEach(a => lines.push('- ' + a));
  lines.push(
    '',
    rows.length === 1 ? 'Here is the best match:' : 'Here are the top ' + rows.length + ' matches:',
    ''
  );
  rows.forEach((r, i) => {
    lines.push(
      (i + 1) + '. ' + String(r.product_name).trim(),
      'Price: ' + inr(r.price_inr),
      'RAM: ' + r.ram_gb + ' GB',
      'Storage: ' + (r.storage_gb + ' GB ' + (r.storage_type || '')).trim(),
      'Processor: ' + (r.processor || 'Not specified'),
      'Operating system: ' + (r.operating_system || 'Not specified'),
      ''
    );
  });
  lines.push('Please confirm the latest price and availability with the seller before purchasing.');
}

lines.push('', 'Regards,', 'Customer Support');

return [{ json: { reply: lines.join('\n') } }];

const rows = $input.all();

function parsePrice(value) {
  const match = String(value ?? "").replace(/,/g, "").match(/\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : null;
}

function parseRam(value, title) {
  const text = `${value ?? ""} ${title ?? ""}`;
  const match = text.match(/(\d+)\s*GB\s*(?:DDR\d*)?\s*(?:RAM)?/i);
  return match ? Number(match[1]) : null;
}

function parseSsdGB(value, title) {
  // Prefer the combined RAM/storage description, then the product title.
  for (const text of [String(value ?? ""), String(title ?? "")]) {
    const match = text.match(/(\d+(?:\.\d+)?)\s*(TB|GB)\s*SSD\b/i);
    if (match) {
      return Math.round(
        Number(match[1]) * (match[2].toUpperCase() === "TB" ? 1024 : 1)
      );
    }
  }
  return null;
}

return rows.map(({ json: row }) => {
  const title = String(row.title ?? "");
  const ramStorage = String(row.RAM ?? "");
  const osMatch = title.match(/\b(Windows\s+\d+(?:\s+\w+){0,2})/i);

  return {
    json: {
      product_name: title,
      price_inr: parsePrice(row.price),
      ram_gb: parseRam(ramStorage, title),
      ssd_gb: parseSsdGB(ramStorage, title),
      processor: row.Processor || null,
      operating_system: osMatch ? osMatch[1] : null,
      display: row.SSD
        ? String(row.SSD).replace(/^Display:\s*/i, "")
        : null,
      warranty: null,
      source: "Laptop CSV - GitHub Gist"
    }
  };
});

// Normalizes the customer's requirements into numbers the database query can use.
const x = $input.first().json.output ?? $input.first().json;
const assumptions = [];

function parseMoney(text) {
  if (!text) return null;
  const t = String(text).toLowerCase().replace(/[₹,]/g, '').replace(/rs\.?/g, '');
  const m = t.match(/(\d+(?:\.\d+)?)\s*(k|thousand|lakh|lakhs|lac|lacs|l)?\b/);
  if (!m) return null;
  let n = parseFloat(m[1]);
  const unit = m[2];
  if (unit === 'k' || unit === 'thousand') n *= 1000;
  else if (unit) n *= 100000;
  return Math.round(n);
}

function parseRam(text) {
  if (!text) return null;
  const t = String(text).toLowerCase();
  const withGb = t.match(/(\d+)\s*gb/);
  if (withGb) return parseInt(withGb[1], 10);
  const bare = t.match(/\b(\d+)\b/);
  if (bare && parseInt(bare[1], 10) <= 128) return parseInt(bare[1], 10);
  if (/high|more|lot|max|best|large|heavy/.test(t)) return 16;
  if (/good|decent|enough/.test(t)) return 8;
  return null;
}

function parseStorageGb(text) {
  if (!text) return null;
  const m = String(text).toLowerCase().match(/(\d+(?:\.\d+)?)\s*(tb|gb)/);
  if (!m) return null;
  return Math.round(parseFloat(m[1]) * (m[2] === 'tb' ? 1000 : 1));
}

function parseCount(text) {
  if (!text) return null;
  const t = String(text).toLowerCase();
  const digits = t.match(/\d+/);
  if (digits) return parseInt(digits[0], 10);
  const words = { one: 1, a: 1, single: 1, two: 2, three: 3, four: 4, five: 5 };
  for (const [w, n] of Object.entries(words)) {
    if (new RegExp('\\b' + w + '\\b').test(t)) return n;
  }
  return null;
}

const budget = parseMoney(x.budget_text);
const ramText = String(x.ram_text ?? '');
const minRam = parseRam(ramText);
const minStorage = parseStorageGb(x.storage_text);
const requested = parseCount(x.quantity_text);
const resultCount = Math.min(Math.max(requested ?? 3, 1), 5);
const brand = x.brand ? String(x.brand).trim() : null;

if (budget) assumptions.push('I read your budget as up to ₹' + budget.toLocaleString('en-IN') + '.');
if (minRam && !/\d/.test(ramText)) assumptions.push('I read "' + ramText + '" as ' + minRam + ' GB of RAM or more.');
if (requested === null) assumptions.push('You did not say how many, so I am showing the top ' + resultCount + '.');

const needsClarification = !budget && !minRam && !minStorage && !brand;

return [{
  json: {
    budget_max_inr: budget,
    min_ram_gb: minRam,
    min_storage_gb: minStorage,
    brand,
    result_count: resultCount,
    needs_clarification: needsClarification,
    assumptions
  }
}];
